/**
 * The "generated by nvaid — do not edit" notice, and frontmatter-safe insertion of it.
 * Shared by the skill/command generator and the rules sync so every generated file
 * (skills, commands, AND nvaid/rules/*) carries the same marker and is drift-checkable.
 */

export const DO_NOT_EDIT =
  "<!-- generated by nvaid — do not edit. Run `nvaid update` to regenerate. -->";

/**
 * Add the notice WITHOUT breaking YAML frontmatter. Frontmatter must start on line 1 (a
 * leading comment makes the parser miss it). If the body opens with a `---` frontmatter
 * block, insert the notice right after that block closes; otherwise put it at the top.
 */
export function withHeader(body: string): string {
  if (body.startsWith("---\n")) {
    const end = body.indexOf("\n---", 4); // close of the frontmatter block
    if (end !== -1) {
      const closeLineEnd = body.indexOf("\n", end + 1); // end of the closing `---` line
      const cut = closeLineEnd === -1 ? body.length : closeLineEnd + 1;
      const front = body.slice(0, cut);
      const rest = body.slice(cut);
      return `${front}\n${DO_NOT_EDIT}\n${rest}`;
    }
  }
  return `${DO_NOT_EDIT}\n\n${body}`;
}
